insert into public.reading_texts (code, cefr, text_type, situation, module_order, title_ua, title_hr, body_hr, body_ua, glossary, questions, word_count, known_ratio, order_index, status, source, published_at)
values ('RD-A2-042', 'A2', 'news', null, 9, 'Помаранчеве попередження', 'Narančasto upozorenje za Dalmaciju',
        'Za Dalmaciju je izdano narančasto upozorenje zbog olujnog vjetra. Sutra dolazi bura, a na moru će biti valovi do četiri metra. Možda će biti prekid plovidbe i problema na autocesti. Ljudi trebaju izbjegavati boravak vani i skloniti se na sigurno mjesto. Zatvorite prozore i ne ostavljajte stvari na balkonu. Zbog suhog vremena opasnost od šumskih požara je velika, pa vrijedi zabrana loženja vatre. Ako ste u opasnosti, nazovite hitne službe na broj 112.',
        'Для Далмації оголошено помаранчеве попередження через штормовий вітер. Завтра прийде бура, а на морі будуть хвилі до чотирьох метрів. Можливі припинення руху суден і проблеми на автомагістралі. Людям слід уникати перебування надворі й сховатися в безпечному місці. Зачиніть вікна й не залишайте речей на балконі. Через суху погоду небезпека лісових пожеж велика, тож діє заборона розпалювати вогонь. Якщо ви в небезпеці, телефонуйте до екстрених служб за номером 112.',
