-- Журнал перевірки (один запис на текст)
insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
select 'reading_text', r.id, null, r.status, 'auto_passed', 'ai', '[]'::jsonb, 'Бета: тексти для читання A2 за програмою A2 v2 (4 на модуль), reading_a2_v2 2026-11-13. Знайомі слова — уроки A0, A1 і A2 до модуля тексту. Потрібна перевірка носієм.'
from public.reading_texts r
where r.code in ('RD-A2-033', 'RD-A2-034', 'RD-A2-035', 'RD-A2-036', 'RD-A2-037', 'RD-A2-038', 'RD-A2-039', 'RD-A2-040', 'RD-A2-041', 'RD-A2-042', 'RD-A2-043', 'RD-A2-044')
  and not exists (select 1 from public.content_reviews c where c.entity_id = r.id and c.notes = 'Бета: тексти для читання A2 за програмою A2 v2 (4 на модуль), reading_a2_v2 2026-11-13. Знайомі слова — уроки A0, A1 і A2 до модуля тексту. Потрібна перевірка носієм.');

-- Самоперевірка: якщо щось не так — усе відкочується
do $$
declare v_total int; v_bad int;
begin
  select count(*) into v_total from public.reading_texts
   where code in ('RD-A2-033', 'RD-A2-034', 'RD-A2-035', 'RD-A2-036', 'RD-A2-037', 'RD-A2-038', 'RD-A2-039', 'RD-A2-040', 'RD-A2-041', 'RD-A2-042', 'RD-A2-043', 'RD-A2-044') and cefr = 'A2' and status = 'PUBLISHED' and source = 'claude_reading_a2_v2' and module_order between 1 and 14;
  select count(*) into v_bad from public.reading_texts r where r.code in ('RD-A2-033', 'RD-A2-034', 'RD-A2-035', 'RD-A2-036', 'RD-A2-037', 'RD-A2-038', 'RD-A2-039', 'RD-A2-040', 'RD-A2-041', 'RD-A2-042', 'RD-A2-043', 'RD-A2-044')
     and (jsonb_array_length(r.questions) <> 3 or r.known_ratio < 0.9
          or exists (select 1 from jsonb_array_elements(r.glossary) e
                     where e->>'pos' is null or coalesce(e->>'ua', '') = ''
                        or (e->>'gram' is null and e->>'form' <> lower(e->>'lemma'))));
  if v_total <> 12 then raise exception 'Нових текстів A2 %, очікувалось 12 (код уже зайнятий іншим текстом?)', v_total; end if;
  if v_bad > 0 then raise exception '% текстів без питань, словничка чи граматичних підказок', v_bad; end if;
  raise notice 'Готово: нових текстів A2 у частині 2 — % (RD-A2-033 … RD-A2-044)', v_total;
end $$;

commit;
